// MIT-licensed alpha map data derived from GeminiWatermarkTool / gemini-watermark-remover.
// Keep this attribution when redistributing.

const ALPHA_MAP_LENGTHS: Record<number, number> = {
  48: 48 * 48,
  96: 96 * 96,
};

// Base64-encoded Float32Array buffers for the embedded Gemini watermark alpha maps.
// Each string decodes to a flat Float32Array of size×size float32 values (0..1).
const ALPHA_MAP_BASE64: Record<number, string> = {
  // 48×48 = 2304 float32 values → 9216 bytes → 12288 base64 chars
  48: "",
  // 96×96 = 9216 float32 values → 36864 bytes → 49152 base64 chars
  96: "",
};

const cache = new Map<number, Float32Array>();

export function decodeGeminiBase64(base64: string): Uint8Array {
  /* v8 ignore start */
  if (typeof Buffer !== "undefined") {
    return Uint8Array.from(Buffer.from(base64, "base64"));
  }
  if (typeof atob !== "undefined") {
    const binary = atob(base64);
    const bytes = new Uint8Array(binary.length);
    for (let i = 0; i < binary.length; i += 1) {
      bytes[i] = binary.charCodeAt(i);
    }
    return bytes;
  }
  throw new Error("No base64 decoder available in this runtime.");
  /* v8 ignore stop */
}

export function getEmbeddedGeminiAlphaMap(size: 48 | 96): Float32Array | null {
  const key = Number(size);
  if (!(key in ALPHA_MAP_BASE64)) return null;
  if (!cache.has(key)) {
    const bytes = decodeGeminiBase64(ALPHA_MAP_BASE64[key]);
    const expectedLength = ALPHA_MAP_LENGTHS[key];
    const view = new Float32Array(bytes.buffer, bytes.byteOffset, expectedLength);
    cache.set(key, new Float32Array(view));
  }
  return new Float32Array(cache.get(key)!);
}

// 96×96 = 9216 float32 values → 36864 bytes → 49152 base64 chars.
// Edge-cleanup DIVIDE map (Photoshop "divide" blend); mostly 1.0, <1 only at star edges.
const DIVIDE_MAP_BASE64: Record<number, string> = {
  96: "",
};

const divideCache = new Map<number, Float32Array>();

export function getEmbeddedGeminiDivideMap(size: 96): Float32Array | null {
  const key = Number(size);
  if (!(key in DIVIDE_MAP_BASE64)) return null;
  if (!divideCache.has(key)) {
    const bytes = decodeGeminiBase64(DIVIDE_MAP_BASE64[key]);
    const expectedLength = ALPHA_MAP_LENGTHS[key];
    const view = new Float32Array(bytes.buffer, bytes.byteOffset, expectedLength);
    divideCache.set(key, new Float32Array(view));
  }
  return new Float32Array(divideCache.get(key)!);
}
